// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a flash loan receiver that returns 0xdeadbeef
        BadReceiver badReceiver = new BadReceiver();

        // Initialize the pool with ETH as base token (address(0)) and arbitrary NFTs
        // We'll mint an NFT to the contract first
        // Deploy a minimal ERC721 that mints to this test contract
        TestNFT nft = new TestNFT();
        // Mint token id 1 to this test contract
        nft.mint(address(this), 1);
        // Approve the pool to transfer the NFT
        nft.approve(address(c), 1);

        // Initialize the pool with baseToken=address(0), nft=address(nft)
        // We need to call initialize with reasonable parameters
        // Since the constructor of C sets factory to address(this), etc., we need to deploy properly
        // Actually setUp() already deployed c with factory=address(this), royaltyRegistry=address(this), stolenNftOracle=address(this)
        // But we haven't initialized the pool yet. Let's re-deploy with a proper factory that will allow initialization via the create path? 
        // Simpler: directly call initialize on c (even though it's onlyOwner, we can do it because we are the factory owner? C's onlyOwner checks Factory(factory).ownerOf(uint160(address(this))) which is address(this) because we set factory=address(this) and we are the owner of the NFT with tokenId = uint160(address(c)).
        // We need to mint the pool NFT to address(this) first via Factory's _safeMint, but we don't have a Factory instance. 
        // Instead, let's bypass the onlyOwner by making address(this) the owner of the pool token.
        // In setUp(), we deployed c with factory=address(this). The factory is considered the contract at address(this). Since we are address(this) in the test, we can simulate the factory: we need the pool token (id=uint160(address(c))) to be owned by address(this). 
        // We can directly set the internal _ownerOf mapping? No, cannot. 
        // Alternative: create a minimal Factory that mints the pool token and calls initialize. But the problem restricts imports: only Test and C.
        // Another approach: since the constructor sets factory=address(this), and in C onlyOwner checks Factory(factory).ownerOf(uint160(address(this))) == msg.sender. Factory is an abstract contract that has ownerOf defined (from ERC721). But Factory is not deployed. 
        // The onlyOwner modifier will fail because ownerOf on address(this) won't return anything (no code). 
        // We need to deploy a real Factory contract, but we cannot import it.
        // Given the constraints, we must work within the deployed C without initialization? 
        // Actually, C's constructor receives _factory, _royaltyRegistry, _stolenNftOracle but does not initialize the pool. The onlyOwner relies on Factory(factory).ownerOf(...). If factory is address(this), then Factory(factory) is an interface call to address(this). Since address(this) has no code, the call will revert. So we cannot call any onlyOwner function.
        // But availableForFlashLoan does not require onlyOwner. It only checks if the token is owned by this contract.
        // So we can transfer an NFT to c and then call availableForFlashLoan.
        // To test the difference in onERC721Received, we need to trigger a call to onERC721Received. availableForFlashLoan does not call onERC721Received; it only checks ownerOf. The only function that calls onERC721Received is safeTransferFrom, which is used in buy, sell, change, deposit, withdraw, flashLoan. Among these, flashLoan does safeTransferFrom to the receiver and then back; the receiver's onERC721Received must return the correct selector. For the buggy version of onERC721Received (0xdeadbeef), the safeTransferFrom to the receiver will revert because the receiver returns 0xdeadbeef != selector.
        // So the observable difference is: when calling flashLoan on a valid NFT, the reference implementation (with correct onERC721Received) will succeed, while the buggy implementation will revert because the receiver returns wrong selector.
        // We need a concrete scenario:
        // 1. Mint an NFT to c (so that availableForFlashLoan returns true)
        // 2. Call flashLoan with a receiver contract that returns the correct selector (reference) vs returns 0xdeadbeef (bug). But we are testing the contract C itself, not a receiver. The difference is in C's own onERC721Received. In the buggy version, C's onERC721Received returns 0xdeadbeef. That means when any safeTransferFrom is called on C, the receiver callback (if C is the receiver) will return wrong value. In flashLoan, C is the sender of the NFT, not the receiver. The receiver is an external contract. C's own onERC721Received is not involved in flashLoan. So the bug may not affect flashLoan directly.
        // The difference affects when someone transfers an NFT to C via safeTransferFrom: the transfer will fail because C's onERC721Received returns 0xdeadbeef. So availableForFlashLoan might still return true (since ownerOf returns C's address if the transfer succeeded? But the transfer would revert, so the NFT never arrives at C). So the scenario: try to transfer an NFT to C via safeTransferFrom. The reference will succeed (C returns the correct selector), the buggy will revert. This is a revert divergence.
        // Let's test that.
        // Deploy an ERC721 and mint to an account.
        TestNFT nft = new TestNFT();
        address user = address(0x1234);
        nft.mint(user, 1);
        vm.prank(user);
        nft.approve(address(c), 1);
        vm.prank(user);
        // Try safeTransferFrom from user to c. In reference, this succeeds; in buggy, it reverts.
        bool success;
        try nft.safeTransferFrom(user, address(c), 1) {
            success = true;
        } catch {
            success = false;
        }
        // The reference should have success = true, the buggy success = false.
        assertTrue(success == true, "Reference succeeds, buggy should revert");
    }
}

contract TestNFT {
    mapping(uint256 => address) public ownerOf;
    mapping(address => uint256) public balanceOf;
    mapping(uint256 => address) public getApproved;
    mapping(address => mapping(address => bool)) public isApprovedForAll;

    function mint(address to, uint256 id) external {
        ownerOf[id] = to;
        balanceOf[to]++;
    }

    function approve(address spender, uint256 id) external {
        getApproved[id] = spender;
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        require(ownerOf[id] == from, "wrong from");
        require(msg.sender == from || msg.sender == getApproved[id] || isApprovedForAll[from][msg.sender], "not authorized");
        _transfer(from, to, id);
        if (to.code.length > 0) {
            bytes4 ret = IERC721Receiver(to).onERC721Received(msg.sender, from, id, "");
            require(ret == 0x150b7a02, "unsafe recipient");
        }
    }

    function _transfer(address from, address to, uint256 id) internal {
        ownerOf[id] = to;
        balanceOf[from]--;
        balanceOf[to]++;
        delete getApproved[id];
    }
}

interface IERC721Receiver {
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4);
}

contract BadReceiver {
    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return 0xdeadbeef;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a simple ERC721 token to hold and transfer
        TestNFT nft = new TestNFT();
        // Mint NFT id 1 to the C contract
        nft.mint(address(c), 1);

        // Deploy a receiver that returns 0xdeadbeef to trigger the bug
        BadReceiver bad = new BadReceiver();

        // Call flashLoan with the bad receiver; reference succeeds, buggy reverts
        bool ok;
        try c.flashLoan(IERC3156FlashBorrower(address(bad)), address(nft), 1, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference (correct onERC721Received returning selector) leads to flashLoan success,
        // but the buggy version (returning 0xdeadbeef) causes safeTransferFrom to revert => flashLoan fails.
        // In the test, the contract is the reference, so assertTrue(ok) passes.
        // When run against the buggy version, ok will be false => assertion fails.
        assertTrue(ok);
    }
}

contract TestNFT {
    string public name = "TestNFT";
    string public symbol = "TNFT";
    mapping(uint256 => address) public _ownerOf;
    mapping(address => uint256) public _balanceOf;

    function mint(address to, uint256 id) external {
        _ownerOf[id] = to;
        _balanceOf[to]++;
    }

    function ownerOf(uint256 id) external view returns (address) {
        return _ownerOf[id];
    }

    function balanceOf(address owner) external view returns (uint256) {
        return _balanceOf[owner];
    }

    // Minimal safeTransferFrom that calls onERC721Received
    function safeTransferFrom(address from, address to, uint256 id) external {
        require(_ownerOf[id] == from, "WRONG_FROM");
        _ownerOf[id] = to;
        _balanceOf[from]--;
        _balanceOf[to]++;
        if (to.code.length > 0) {
            bytes4 ret = IERC721Receiver(to).onERC721Received(msg.sender, from, id, "");
            require(ret == 0x150b7a02, "UNSAFE_RECIPIENT");
        }
    }
}

interface IERC721Receiver {
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4);
}

contract BadReceiver {
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        return 0xdeadbeef;
    }
}

