contract InvMutTest is Test {
    C c;
    Receiver receiver;
    address nft;
    uint256 tokenId = 1;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
        receiver = new Receiver();
        // Deploy a minimal ERC721 to use as the NFT
        nft = address(new ERC721Mock());
        // Initialize the C contract with the NFT and baseToken = address(0) (ETH)
        c.initialize(
            address(0),               // baseToken = ETH
            nft,                      // nft
            1_000_000e18,             // virtualBaseTokenReserves
            1_000_000e18,             // virtualNftReserves
            0,                        // changeFee
            0,                        // feeRate
            bytes32(0),               // merkleRoot
            false,                    // useStolenNftOracle
            false                     // payRoyalties
        );
        // Mint the NFT to the C contract
        ERC721Mock(nft).mint(address(c), tokenId);
    }

    function testRegression_property() public {
        // Call buy as the receiver contract, sending enough ETH for the buy
        // The buy must transfer the NFT to receiver
        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = tokenId;
        uint256[] memory tokenWeights = new uint256[](1);
        tokenWeights[0] = 1e18;
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        // We need to set up the receiver as the caller
        vm.deal(address(receiver), 10e18);
        vm.prank(address(receiver));
        // This should succeed in reference (because receiver returns selector, wait, no: reference's onERC721Received returns selector, but our receiver returns 0xdeadbeef. So both should revert? Let's adjust: We'll use a receiver that returns the correct selector in reference and one that returns 0xdeadbeef in buggy? No, we cannot change contracts between runs. We must use the same receiver for both. The difference is in the C contract's own onERC721Received? No, the bug is in ERC721TokenReceiver abstract contract, which C inherits? Actually, C does not inherit ERC721TokenReceiver; it only inherits ERC721TokenReceiver? Looking at the code: contract C is ERC721TokenReceiver { ... } So C itself overrides onERC721Received. The bug is in the abstract ERC721TokenReceiver, but C overrides it? No, looking at C's code: it does not define onERC721Received. It inherits from ERC721TokenReceiver, which has the buggy version returning 0xdeadbeef? Wait, the bug is in the abstract contract ERC721TokenReceiver, but C does not override it, so C uses the inherited version. So C's onERC721Received returns 0xdeadbeef. So when C calls safeTransferFrom to itself (e.g., during sell), it will fail because C returns 0xdeadbeef. For the reference, we assume the original ERC721TokenReceiver returns the correct selector, so it works. For the buggy version, C returns 0xdeadbeef, so safeTransferFrom to C will fail. So we need a scenario where safeTransferFrom is called to the C contract itself. For example, during sell, the contract calls safeTransferFrom from seller to itself. In the reference, that works; in the buggy, it reverts. So call sell with a valid NFT that the contract does NOT hold? Actually, sell expects the seller to transfer NFT to the contract. If the seller is the contract itself? No. Let's think: sell calls ERC721(nft).safeTransferFrom(msg.sender, address(this), tokenIds[i]); So the receiver is the contract itself. The check is on the receiver's onERC721Received (i.e., the C contract). So if C returns 0xdeadbeef, the transfer will fail. In the reference, C returns the correct selector, so it succeeds. So we can test: first deposit an NFT into the contract (so it holds it? No, sell transfers FROM msg.sender TO the contract, so we need the NFT owned by msg.sender. Then call sell, and in the reference it succeeds (NFT is transferred to contract), but in the buggy it reverts because safeTransferFrom fails. So we assert that after calling sell with a valid NFT owned by msg.sender, in the reference the contract ends up owning the NFT, but in the buggy version it reverts and the NFT remains with msg.sender. We'll catch the revert.
        // We need an NFT that exists and is owned by the caller (receiver)
        ERC721Mock(nft).mint(address(receiver), tokenId);
        // Approve the C contract to transfer the NFT
        vm.prank(address(receiver));
        ERC721Mock(nft).approve(address(c), tokenId);

        uint256[] memory sellTokenIds = new uint256[](1);
        sellTokenIds[0] = tokenId;
        uint256[] memory sellTokenWeights = new uint256[](1);
        sellTokenWeights[0] = 1e18;

        bool success;
        try c.sell(sellTokenIds, sellTokenWeights, proof, new IStolenNftOracle.Message[](0)) {
            success = true;
        } catch {
            success = false;
        }

        // In the reference, safeTransferFrom succeeds so the contract gets the NFT and ownerOf(tokenId) == address(c)
        // In the buggy version, safeTransferFrom fails so the sell reverts and ownerOf(tokenId) != address(c) (still receiver)
        assertTrue(success && ERC721Mock(nft).ownerOf(tokenId) == address(c));
    }
}

contract ERC721Mock {
    string public name = "Mock";
    string public symbol = "MCK";
    mapping(uint256 => address) public _ownerOf;
    mapping(address => uint256) public _balanceOf;
    mapping(uint256 => address) public getApproved;
    mapping(address => mapping(address => bool)) public isApprovedForAll;

    function mint(address to, uint256 id) external {
        _ownerOf[id] = to;
        _balanceOf[to]++;
    }

    function ownerOf(uint256 id) external view returns (address) {
        address owner = _ownerOf[id];
        require(owner != address(0), "NOT_MINTED");
        return owner;
    }

    function balanceOf(address owner) external view returns (uint256) {
        return _balanceOf[owner];
    }

    function approve(address spender, uint256 id) external {
        getApproved[id] = spender;
    }

    function setApprovalForAll(address operator, bool approved) external {
        isApprovedForAll[msg.sender][operator] = approved;
    }

    function transferFrom(address from, address to, uint256 id) external {
        require(from == _ownerOf[id], "WRONG_FROM");
        require(to != address(0), "INVALID_RECIPIENT");
        require(msg.sender == from || isApprovedForAll[from][msg.sender] || msg.sender == getApproved[id], "NOT_AUTHORIZED");
        unchecked {
            _balanceOf[from]--;
            _balanceOf[to]++;
        }
        _ownerOf[id] = to;
        delete getApproved[id];
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        transferFrom(from, to, id);
        require(
            to.code.length == 0 ||
                IERC721TokenReceiver(to).onERC721Received(msg.sender, from, id, "") ==
                IERC721TokenReceiver.onERC721Received.selector,
            "UNSAFE_RECIPIENT"
        );
    }
}

