// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a receiver contract that returns 0xdeadbeef
        ReceiverBad receiver = new ReceiverBad();
        // Mint an NFT to the C contract
        vm.deal(address(this), 1 ether);
        c.deposit{value: 1 ether}(new uint256[](0), 0); // no NFTs, just to set up state
        // We need to provide a token that C can use as NFT. Since C is deployed with address(this) as nft, we need to ensure an ERC721 token at that address.
        // But for simplicity, we'll use a mock NFT deployed separately.
        // However, to keep it simple within the constraints, we'll use a different approach: we directly call flashLoan with token = address(c) (which is an ERC721Receiver) and tokenId = 1.
        // But C's availableForFlashLoan checks ownerOf, which would revert for non-existent token. So we need a real NFT.
        // Let's deploy a minimal ERC721 and mint to c.
        MockNFT nft = new MockNFT();
        nft.mint(address(c), 1);
        // Now call flashLoan with receiver that returns 0xdeadbeef
        bool ok;
        try c.flashLoan(IERC3156FlashBorrower(address(receiver)), address(nft), 1, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, flashLoan succeeds; in buggy, it reverts.
        assertTrue(ok);
    }
}

contract ReceiverBad {
    function onFlashLoan(address, address, uint256, uint256, bytes calldata) external pure returns (bytes32) {
        return keccak256("onFlashLoan");
    }
    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return 0xdeadbeef;
    }
}

contract MockNFT {
    mapping(uint256 => address) public ownerOf;
    function mint(address to, uint256 id) external { ownerOf[id] = to; }
    function safeTransferFrom(address from, address to, uint256 id) external {
        require(ownerOf[id] == from);
        ownerOf[id] = to;
        // Check receiver
        if (to.code.length > 0) {
            bytes4 ret = IERC721Receiver(to).onERC721Received(msg.sender, from, id, "");
            require(ret == 0x150b7a02, "UNSAFE");
        }
    }
}

interface IERC721Receiver {
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4);
}

interface IERC3156FlashBorrower {
    function onFlashLoan(address initiator, address token, uint256 amount, uint256 fee, bytes calldata data) external returns (bytes32);
